function groupBy<T, K extends keyof T>(items: T[], key: K): Array<[T[K], T[]]> {
  const groups: Record<string, T[]> = {};
  for (const item of items) {
    const name = String(item[key]);
    (groups[name] ??= []).push(item);
  }
  // TODO: object keys are always strings, and integer-like keys are reordered
  return Object.entries(groups) as unknown as Array<[T[K], T[]]>;
}

solution:
function groupBy<T, K extends keyof T>(items: readonly T[], key: K): Array<[T[K], T[]]> {
  const groups = new Map<T[K], T[]>();
  for (const item of items) {
    const value = item[key];
    const bucket = groups.get(value);
    if (bucket) bucket.push(item);
    else groups.set(value, [item]);
  }
  return [...groups];
}

`K extends keyof T` rejects a key that is not a property of the items, and `T[K]` gives each group key the property's own type, so grouping by `age` returns `number` keys. A `Map` compares keys with SameValueZero, so `1` and `'1'` stay apart, and it iterates in insertion order, so groups come out in order of first appearance; spreading it yields the `[key, items]` pairs directly. The starter's object stringifies keys and lists integer-like keys first, which breaks both type and order. Each item is touched once, so the work is O(n) and the grouping does not copy the items, only references them. Taking `readonly T[]` documents that the input is not modified.

